    mediaNoAudioBody: "\uC774 \uBE44\uB514\uC624\uC758 \uC624\uB514\uC624 \uCF54\uB371({codec})\uC740 \uB0B4\uC7A5 \uD50C\uB808\uC774\uC5B4\uC5D0\uC11C \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC544 \uC571 \uB0B4 \uC7AC\uC0DD \uC2DC \uC18C\uB9AC\uAC00 \uB098\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uD30C\uC77C\uC740 \uC6D0\uBCF8 \uADF8\uB300\uB85C \uC0BD\uC785\uB418\uBA70 \uB0B4\uBCF4\uB0B8 \uD6C4 PowerPoint\uC5D0\uC11C\uB294 \uC815\uC0C1\uC801\uC73C\uB85C \uC7AC\uC0DD\uB429\uB2C8\uB2E4.",
    mediaAviBody: "AVI \uD615\uC2DD\uC740 \uB0B4\uC7A5 \uD50C\uB808\uC774\uC5B4\uC5D0\uC11C \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC544 \uC571 \uB0B4\uC5D0\uC11C \uC7AC\uC0DD\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uD30C\uC77C\uC740 \uC6D0\uBCF8 \uADF8\uB300\uB85C \uC0BD\uC785\uB418\uBA70 \uB0B4\uBCF4\uB0B8 \uD6C4 PowerPoint\uC5D0\uC11C\uB294 \uC7AC\uC0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    legacyPptTitle: ".ppt \uD615\uC2DD\uC744 \uC5F4 \uC218 \uC5C6\uC74C",
    legacyPptBody: 'PowerPoint 97-2003(.ppt) \uC774\uC9C4 \uD615\uC2DD\uC785\uB2C8\uB2E4. \uC774 \uC571\uC740 .pptx\uB9CC \uC9C0\uC6D0\uD569\uB2C8\uB2E4. PowerPoint \uB4F1\uC5D0\uC11C \uC5F4\uC5B4 ".pptx\uB85C \uC800\uC7A5" \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.',
    legacyPptOk: "\uD655\uC778",
    encryptedPptxTitle: "\uC554\uD638\uB85C \uBCF4\uD638\uB41C \uD30C\uC77C\uC744 \uC5F4 \uC218 \uC5C6\uC74C",
    encryptedPptxBody: "\uC774 \uD30C\uC77C\uC740 \uC554\uD638\uD654\uB41C Office \uBB38\uC11C\uC785\uB2C8\uB2E4. \uC554\uD638 \uBCF4\uD638 \uD30C\uC77C\uC740 \uC544\uC9C1 \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. PowerPoint\uC5D0\uC11C \uC554\uD638\uB97C \uD574\uC81C\uD558\uACE0 \uC800\uC7A5\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    chartSimplifyTitle: "\uD3B8\uC9D1\uD558\uBA74 \uC774 \uCC28\uD2B8\uAC00 \uB2E8\uC21C\uD654\uB429\uB2C8\uB2E4",
    chartSimplifyBody: "\uC774 \uCC28\uD2B8\uB294 \uC678\uBD80 \uD30C\uC77C\uC5D0\uC11C \uAC00\uC838\uC654\uC2B5\uB2C8\uB2E4. \uD3B8\uC9D1\uD558\uBA74 \uC774 \uC571\uC758 \uBAA8\uB378\uB85C \uC7AC\uAD6C\uC131\uB418\uC5B4 \uC22B\uC790 \uC11C\uC2DD, \uCD94\uC138\uC120, \uC624\uCC28 \uB9C9\uB300, \uC694\uC18C\uBCC4 \uC2A4\uD0C0\uC77C \uB4F1 \uC138\uBD80 \uC11C\uC2DD\uC774 \uC190\uC2E4\uB429\uB2C8\uB2E4.",
    chartSimplifyOk: "\uACC4\uC18D \uD3B8\uC9D1",
