    closeUnsavedDetail: "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0438\u0445 \u043F\u0435\u0440\u0435\u0434 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435\u043C?",
    btnDontSave: "\u041D\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C",
    btnCancel: "\u041E\u0442\u043C\u0435\u043D\u0430",
    mediaUnsupportedTitle: "\u042D\u0442\u043E \u0432\u0438\u0434\u0435\u043E \u043C\u043E\u0436\u0435\u0442 \u043D\u0435 \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u044C\u0441\u044F \u0432 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438",
    mediaNoAudioBody: "\u0410\u0443\u0434\u0438\u043E\u043A\u043E\u0434\u0435\u043A \u0432\u0438\u0434\u0435\u043E ({codec}) \u043D\u0435 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u044B\u043C \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u0442\u0435\u043B\u0435\u043C: \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0432 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438 \u0431\u0443\u0434\u0435\u0442 \u0431\u0435\u0437 \u0437\u0432\u0443\u043A\u0430. \u0424\u0430\u0439\u043B \u0432\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439 \u0438 \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u043E \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u0432 PowerPoint \u043F\u043E\u0441\u043B\u0435 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0430.",
    mediaAviBody: "\u0424\u043E\u0440\u043C\u0430\u0442 AVI \u043D\u0435 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u044B\u043C \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u0442\u0435\u043B\u0435\u043C, \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0432 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438 \u043D\u0435\u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E. \u0424\u0430\u0439\u043B \u0432\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439 \u0438 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u0432 PowerPoint \u043F\u043E\u0441\u043B\u0435 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0430.",
    legacyPptTitle: "\u041D\u0435 \u0443\u0434\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0444\u043E\u0440\u043C\u0430\u0442 .ppt",
    legacyPptBody: "\u042D\u0442\u043E \u0434\u0432\u043E\u0438\u0447\u043D\u044B\u0439 \u0444\u0430\u0439\u043B PowerPoint 97-2003 (.ppt). \u041F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E .pptx. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0432 PowerPoint \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0435 \u043A\u0430\u043A .pptx.",
    legacyPptOk: "\u041E\u041A",
    encryptedPptxTitle: "\u041D\u0435 \u0443\u0434\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0444\u0430\u0439\u043B, \u0437\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u043F\u0430\u0440\u043E\u043B\u0435\u043C",
    encryptedPptxBody: "\u042D\u0442\u043E \u0437\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442 Office. \u0424\u0430\u0439\u043B\u044B, \u0437\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0435 \u043F\u0430\u0440\u043E\u043B\u0435\u043C, \u043F\u043E\u043A\u0430 \u043D\u0435 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044E\u0442\u0441\u044F. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0444\u0430\u0439\u043B \u0432 PowerPoint, \u0441\u043D\u0438\u043C\u0438\u0442\u0435 \u043F\u0430\u0440\u043E\u043B\u044C, \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0435 \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
    chartSimplifyTitle: "\u0420\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u0443\u043F\u0440\u043E\u0441\u0442\u0438\u0442 \u044D\u0442\u0443 \u0434\u0438\u0430\u0433\u0440\u0430\u043C\u043C\u0443",
    chartSimplifyBody: "\u042D\u0442\u0430 \u0434\u0438\u0430\u0433\u0440\u0430\u043C\u043C\u0430 \u0438\u0437 \u0432\u043D\u0435\u0448\u043D\u0435\u0433\u043E \u0444\u0430\u0439\u043B\u0430. \u041F\u0440\u0438 \u0440\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0438 \u043E\u043D\u0430 \u0431\u0443\u0434\u0435\u0442 \u043F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0435\u043D\u0430 \u043F\u043E \u043C\u043E\u0434\u0435\u043B\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F; \u0447\u0438\u0441\u043B\u043E\u0432\u044B\u0435 \u0444\u043E\u0440\u043C\u0430\u0442\u044B, \u043B\u0438\u043D\u0438\u0438 \u0442\u0440\u0435\u043D\u0434\u0430, \u043F\u043B\u0430\u043D\u043A\u0438 \u043F\u043E\u0433\u0440\u0435\u0448\u043D\u043E\u0441\u0442\u0435\u0439 \u0438 \u0441\u0442\u0438\u043B\u0438 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u0442\u043E\u0447\u0435\u043A \u0431\u0443\u0434\u0443\u0442 \u043F\u043E\u0442\u0435\u0440\u044F\u043D\u044B.",
