    mediaNoAudioBody: "\u062A\u0631\u0645\u064A\u0632 \u0627\u0644\u0635\u0648\u062A \u0641\u064A \u0627\u0644\u0641\u064A\u062F\u064A\u0648 ({codec}) \u063A\u064A\u0631 \u0645\u062F\u0639\u0648\u0645 \u0641\u064A \u0627\u0644\u0645\u0634\u063A\u0651\u0644 \u0627\u0644\u0645\u062F\u0645\u062C\u060C \u0644\u0630\u0627 \u0633\u064A\u0643\u0648\u0646 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u062F\u0627\u062E\u0644 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0628\u0644\u0627 \u0635\u0648\u062A. \u064A\u062A\u0645 \u062A\u0636\u0645\u064A\u0646 \u0627\u0644\u0645\u0644\u0641 \u0643\u0645\u0627 \u0647\u0648 \u0648\u064A\u0639\u0645\u0644 \u0628\u0634\u0643\u0644 \u0637\u0628\u064A\u0639\u064A \u0641\u064A PowerPoint \u0628\u0639\u062F \u0627\u0644\u062A\u0635\u062F\u064A\u0631.",
    mediaAviBody: "\u062A\u0646\u0633\u064A\u0642 AVI \u063A\u064A\u0631 \u0645\u062F\u0639\u0648\u0645 \u0641\u064A \u0627\u0644\u0645\u0634\u063A\u0651\u0644 \u0627\u0644\u0645\u062F\u0645\u062C \u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u062A\u0634\u063A\u064A\u0644\u0647 \u062F\u0627\u062E\u0644 \u0627\u0644\u062A\u0637\u0628\u064A\u0642. \u064A\u062A\u0645 \u062A\u0636\u0645\u064A\u0646 \u0627\u0644\u0645\u0644\u0641 \u0643\u0645\u0627 \u0647\u0648 \u0648\u064A\u0638\u0644 \u0642\u0627\u0628\u0644\u0627\u064B \u0644\u0644\u062A\u0634\u063A\u064A\u0644 \u0641\u064A PowerPoint \u0628\u0639\u062F \u0627\u0644\u062A\u0635\u062F\u064A\u0631.",
    legacyPptTitle: "\u062A\u0639\u0630\u0651\u0631 \u0641\u062A\u062D \u062A\u0646\u0633\u064A\u0642 .ppt",
    legacyPptBody: "\u0647\u0630\u0627 \u0645\u0644\u0641 PowerPoint 97-2003 (.ppt) \u062B\u0646\u0627\u0626\u064A. \u0627\u0644\u0645\u062F\u0639\u0648\u0645 \u0647\u0648 .pptx \u0641\u0642\u0637. \u0627\u0641\u062A\u062D\u0647 \u0641\u064A PowerPoint \u062B\u0645 \u0627\u062D\u0641\u0638\u0647 \u0628\u0635\u064A\u063A\u0629 .pptx.",
    legacyPptOk: "\u062D\u0633\u0646\u064B\u0627",
    encryptedPptxTitle: "\u062A\u0639\u0630\u0651\u0631 \u0641\u062A\u062D \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0645\u062D\u0645\u064A \u0628\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631",
    encryptedPptxBody: "\u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641 \u0645\u0633\u062A\u0646\u062F Office \u0645\u0634\u0641\u0651\u0631. \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0627\u0644\u0645\u062D\u0645\u064A\u0629 \u0628\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u063A\u064A\u0631 \u0645\u062F\u0639\u0648\u0645\u0629 \u0628\u0639\u062F. \u0627\u0641\u062A\u062D\u0647 \u0641\u064A PowerPoint \u0648\u0623\u0632\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u062B\u0645 \u0627\u062D\u0641\u0638\u0647 \u0648\u062D\u0627\u0648\u0644 \u0645\u062C\u062F\u062F\u064B\u0627.",
    chartSimplifyTitle: "\u0633\u064A\u0624\u062F\u064A \u0627\u0644\u062A\u062D\u0631\u064A\u0631 \u0625\u0644\u0649 \u062A\u0628\u0633\u064A\u0637 \u0647\u0630\u0627 \u0627\u0644\u0645\u062E\u0637\u0637",
    chartSimplifyBody: "\u0647\u0630\u0627 \u0627\u0644\u0645\u062E\u0637\u0637 \u0645\u0646 \u0645\u0644\u0641 \u062E\u0627\u0631\u062C\u064A. \u0639\u0646\u062F \u0627\u0644\u062A\u062D\u0631\u064A\u0631 \u0633\u064A\u064F\u0639\u0627\u062F \u0628\u0646\u0627\u0624\u0647 \u0648\u0641\u0642 \u0646\u0645\u0648\u0630\u062C \u0647\u0630\u0627 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u061B \u0648\u0633\u062A\u064F\u0641\u0642\u062F \u0627\u0644\u062A\u0646\u0633\u064A\u0642\u0627\u062A \u0627\u0644\u062F\u0642\u064A\u0642\u0629 \u0645\u062B\u0644 \u062A\u0646\u0633\u064A\u0642\u0627\u062A \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0648\u062E\u0637\u0648\u0637 \u0627\u0644\u0627\u062A\u062C\u0627\u0647 \u0648\u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u062E\u0637\u0623 \u0648\u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u0646\u0642\u0627\u0637.",
