    errImageNoText: "\u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062A \u0645\u0646 \u0646\u0648\u0639 \u0627\u0644\u0635\u0648\u0631 \u0644\u0627 \u062A\u0648\u0641\u0631 \u0646\u0635\u064B\u0627\u061B \u0648\u0642\u062F \u0623\u064F\u0631\u0633\u0644\u062A \u0627\u0644\u0635\u0648\u0631\u0629 \u0645\u0639 \u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u060C \u064A\u0643\u0641\u064A \u0627\u0644\u0646\u0638\u0631 \u0625\u0644\u064A\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629",
