    errNoModel: "\u0644\u0645 \u064A\u062A\u0645 \u062A\u0643\u0648\u064A\u0646 \u0627\u0633\u0645 \u0627\u0644\u0646\u0645\u0648\u0630\u062C",
    
    errNoDeckAppend: '\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0633\u062A\u0646\u062F \u064A\u0645\u0643\u0646 \u0627\u0644\u0625\u0644\u062D\u0627\u0642 \u0628\u0647 (\u0627\u0644\u062C\u0644\u0633\u0629 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F\u0629). \u0623\u0646\u0634\u0626 \u0627\u0644\u0635\u0641\u062D\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 mode:"replace" \u0623\u0648\u0644\u064B\u0627\u060C \u0623\u0648 \u0623\u0636\u0641 \u0635\u0641\u062D\u0627\u062A \u0628\u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0623\u0635\u0644\u064A\u0629.',
