    errMergeFailed: "\u0641\u0634\u0644 \u062F\u0645\u062C \u0627\u0644\u0634\u0631\u064A\u062D\u0629 (\u0645\u0644\u0641 pptx \u0627\u0644\u0645\u0635\u062F\u0631 \u0623\u062D\u0627\u062F\u064A \u0627\u0644\u0635\u0641\u062D\u0629 \u0644\u0627 \u064A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u0635\u0641\u062D\u0629 \u0635\u0627\u0644\u062D\u0629)",
    errNoDeckReplace: "\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0633\u062A\u0646\u062F \u0645\u0641\u062A\u0648\u062D (\u0627\u0644\u062C\u0644\u0633\u0629 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F\u0629)\u060C \u0641\u0644\u0627 \u064A\u0645\u0643\u0646 \u0625\u0639\u0627\u062F\u0629 \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0635\u0641\u062D\u0629.",
