    errInsertNeedsOne: "\u0648\u0636\u0639 insert_at \u064A\u062A\u0637\u0644\u0628 \u0635\u0641\u062D\u0629 HTML \u0648\u0627\u062D\u062F\u0629 \u0628\u0627\u0644\u0636\u0628\u0637",
    errReplaceFailed: "\u0641\u0634\u0644 \u0627\u0633\u062A\u0628\u062F\u0627\u0644 \u0627\u0644\u0635\u0641\u062D\u0629 \u0641\u064A \u0645\u0643\u0627\u0646\u0647\u0627 (\u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0646\u0642\u0644/\u062D\u0630\u0641 \u0627\u0644\u0635\u0641\u062D\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629)",
