    untitledDeck: "\u05DE\u05E6\u05D2\u05EA \u05DC\u05DC\u05D0 \u05E9\u05DD",
    autosaveFoundTitle: "\u05E0\u05DE\u05E6\u05D0\u05D4 \u05D2\u05E8\u05E1\u05D4 \u05DE\u05E9\u05D5\u05D7\u05D6\u05E8\u05EA",
    autosaveFoundBody: "\u05E7\u05D9\u05D9\u05DE\u05D9\u05DD \u05E9\u05D9\u05E0\u05D5\u05D9\u05D9\u05DD \u05E9\u05DC\u05D0 \u05E0\u05E9\u05DE\u05E8\u05D5 \u05DE\u05D4\u05E4\u05E2\u05DC\u05D4 \u05D4\u05E7\u05D5\u05D3\u05DE\u05EA. \u05DC\u05E9\u05D7\u05D6\u05E8 \u05D0\u05EA \u05D4\u05D2\u05E8\u05E1\u05D4 \u05E9\u05E0\u05E9\u05DE\u05E8\u05D4 \u05D0\u05D5\u05D8\u05D5\u05DE\u05D8\u05D9\u05EA?",
    autosaveRestore: "\u05E9\u05D7\u05D6\u05E8",
    autosaveDiscard: "\u05D4\u05EA\u05E2\u05DC\u05DD",
    closeUnsavedMsg: "\u05D1\u05DE\u05E6\u05D2\u05EA \u05D6\u05D5 \u05D9\u05E9 \u05E9\u05D9\u05E0\u05D5\u05D9\u05D9\u05DD \u05E9\u05DC\u05D0 \u05E0\u05E9\u05DE\u05E8\u05D5.",
    closeUnsavedDetail: "\u05D4\u05D0\u05DD \u05DC\u05E9\u05DE\u05D5\u05E8 \u05D0\u05D5\u05EA\u05DD \u05DC\u05E4\u05E0\u05D9 \u05D4\u05E1\u05D2\u05D9\u05E8\u05D4?",
    btnDontSave: "\u05D0\u05DC \u05EA\u05E9\u05DE\u05D5\u05E8",
    btnCancel: "\u05D1\u05D9\u05D8\u05D5\u05DC",
    mediaUnsupportedTitle: "\u05D9\u05D9\u05EA\u05DB\u05DF \u05E9\u05E1\u05E8\u05D8\u05D5\u05DF \u05D6\u05D4 \u05DC\u05D0 \u05D9\u05D5\u05E4\u05E2\u05DC \u05D1\u05EA\u05D5\u05DA \u05D4\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4",
    mediaNoAudioBody: "\u05DE\u05E7\u05D5\u05D3\u05D3 \u05D4\u05E9\u05DE\u05E2 \u05E9\u05DC \u05D4\u05E1\u05E8\u05D8\u05D5\u05DF ({codec}) \u05D0\u05D9\u05E0\u05D5 \u05E0\u05EA\u05DE\u05DA \u05D1\u05E0\u05D2\u05DF \u05D4\u05DE\u05D5\u05D1\u05E0\u05D4, \u05D5\u05DC\u05DB\u05DF \u05D4\u05D4\u05E4\u05E2\u05DC\u05D4 \u05D1\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4 \u05EA\u05D4\u05D9\u05D4 \u05DC\u05DC\u05D0 \u05E7\u05D5\u05DC. \u05D4\u05E7\u05D5\u05D1\u05E5 \u05DE\u05D5\u05D8\u05DE\u05E2 \u05DB\u05E4\u05D9 \u05E9\u05D4\u05D5\u05D0 \u05D5\u05DE\u05D5\u05E4\u05E2\u05DC \u05DB\u05E8\u05D2\u05D9\u05DC \u05D1-PowerPoint \u05DC\u05D0\u05D7\u05E8 \u05D4\u05D9\u05D9\u05E6\u05D5\u05D0.",
    mediaAviBody: "\u05E4\u05D5\u05E8\u05DE\u05D8 AVI \u05D0\u05D9\u05E0\u05D5 \u05E0\u05EA\u05DE\u05DA \u05D1\u05E0\u05D2\u05DF \u05D4\u05DE\u05D5\u05D1\u05E0\u05D4 \u05D5\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05D4\u05E4\u05E2\u05D9\u05DC\u05D5 \u05D1\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4. \u05D4\u05E7\u05D5\u05D1\u05E5 \u05DE\u05D5\u05D8\u05DE\u05E2 \u05DB\u05E4\u05D9 \u05E9\u05D4\u05D5\u05D0 \u05D5\u05E2\u05D3\u05D9\u05D9\u05DF \u05E0\u05D9\u05EA\u05DF \u05DC\u05D4\u05E4\u05E2\u05DC\u05D4 \u05D1-PowerPoint \u05DC\u05D0\u05D7\u05E8 \u05D4\u05D9\u05D9\u05E6\u05D5\u05D0.",
    legacyPptTitle: "\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05E4\u05EA\u05D5\u05D7 \u05D0\u05EA \u05D4\u05E4\u05D5\u05E8\u05DE\u05D8 \u05D4\u05D9\u05E9\u05DF .ppt",
    legacyPptBody: '\u05D6\u05D4\u05D5 \u05E7\u05D5\u05D1\u05E5 \u05D1\u05D9\u05E0\u05D0\u05E8\u05D9 \u05E9\u05DC PowerPoint 97-2003 (.ppt). \u05E0\u05EA\u05DE\u05DA \u05E8\u05E7 .pptx. \u05E4\u05EA\u05D7 \u05D0\u05D5\u05EA\u05D5 \u05D1-PowerPoint/WPS/Keynote, \u05D1\u05D7\u05E8 "\u05E9\u05DE\u05D9\u05E8\u05D4 \u05D1\u05E9\u05DD .pptx" \u05D5\u05E0\u05E1\u05D4 \u05E9\u05D5\u05D1.',
    legacyPptOk: "\u05D4\u05D1\u05E0\u05EA\u05D9",
    encryptedPptxTitle: "\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05E4\u05EA\u05D5\u05D7 \u05E7\u05D5\u05D1\u05E5 \u05DE\u05D5\u05D2\u05DF \u05D1\u05E1\u05D9\u05E1\u05DE\u05D4",
    encryptedPptxBody: "\u05E7\u05D5\u05D1\u05E5 \u05D6\u05D4 \u05D4\u05D5\u05D0 \u05DE\u05E1\u05DE\u05DA Office \u05DE\u05D5\u05E6\u05E4\u05DF. \u05E7\u05D1\u05E6\u05D9\u05DD \u05DE\u05D5\u05D2\u05E0\u05D9\u05DD \u05D1\u05E1\u05D9\u05E1\u05DE\u05D4 \u05D0\u05D9\u05E0\u05DD \u05E0\u05EA\u05DE\u05DB\u05D9\u05DD \u05E2\u05D3\u05D9\u05D9\u05DF. \u05E4\u05EA\u05D7\u05D5 \u05D0\u05D5\u05EA\u05D5 \u05D1-PowerPoint, \u05D4\u05E1\u05D9\u05E8\u05D5 \u05D0\u05EA \u05D4\u05E1\u05D9\u05E1\u05DE\u05D4, \u05E9\u05DE\u05E8\u05D5 \u05D5\u05E0\u05E1\u05D5 \u05E9\u05D5\u05D1.",
    chartSimplifyTitle: "\u05E2\u05E8\u05D9\u05DB\u05D4 \u05EA\u05E4\u05E9\u05D8 \u05D0\u05EA \u05D4\u05EA\u05E8\u05E9\u05D9\u05DD \u05D4\u05D6\u05D4",
    chartSimplifyBody: "\u05EA\u05E8\u05E9\u05D9\u05DD \u05D6\u05D4 \u05DE\u05D2\u05D9\u05E2 \u05DE\u05E7\u05D5\u05D1\u05E5 \u05D7\u05D9\u05E6\u05D5\u05E0\u05D9. \u05E2\u05E8\u05D9\u05DB\u05D4 \u05EA\u05D1\u05E0\u05D4 \u05D0\u05D5\u05EA\u05D5 \u05DE\u05D7\u05D3\u05E9 \u05DC\u05E4\u05D9 \u05D4\u05DE\u05D5\u05D3\u05DC \u05E9\u05DC \u05D4\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4; \u05E2\u05D9\u05E6\u05D5\u05D1\u05D9 \u05DE\u05E1\u05E4\u05E8\u05D9\u05DD, \u05E7\u05D5\u05D5\u05D9 \u05DE\u05D2\u05DE\u05D4, \u05E4\u05E1\u05D9 \u05E9\u05D2\u05D9\u05D0\u05D4 \u05D5\u05E1\u05D2\u05E0\u05D5\u05E0\u05D5\u05EA \u05DC\u05E4\u05D9 \u05E0\u05E7\u05D5\u05D3\u05D4 \u05D9\u05D0\u05D1\u05D3\u05D5.",
